import numpy as np
from scipy.special import xlogy
from scipy.stats import chi2


def poisson_deviance(y, mu):
    y = np.asarray(y, dtype=float)
    mu = np.asarray(mu, dtype=float)
    return 2 * np.sum(xlogy(y, y / mu) - (y - mu))


def dispersion(y, mu, n_params):
    y = np.asarray(y, dtype=float)
    mu = np.asarray(mu, dtype=float)
    return np.sum((y - mu) ** 2 / mu) / (len(y) - n_params)


def lr_test(dev_small, dev_big, df):
    stat = dev_small - dev_big
    return stat, chi2.sf(stat, df)
